// Batting-led limited-overs match. Opposition uses a disclosed seeded simulation.
const rng=seed=>()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return(seed>>>0)/4294967296;};
export class MatchFlowController {
 constructor(){this.reset();}
 reset({overs=2,batFirst=true,seed=120926}={}){this.overs=[1,2,5,10,20].includes(Number(overs))?Number(overs):2;this.batFirst=batFirst;this.seed=seed;this.player={runs:0,wickets:0,balls:0,extras:0,history:[]};this.opponent=null;this.completed=false;this.committed=new Set();this.result='';this.striker=1;this.nonStriker=2;this.nextBatter=3;if(!batFirst)this.opponent=this.simulateOpponent(null);}
 simulateOpponent(target){const r=rng(this.seed),innings={runs:0,wickets:0,balls:0,extras:0,history:[]};while(innings.balls<this.overs*6&&innings.wickets<10&&(!target||innings.runs<target)){const x=r();innings.balls++;const wicket=x<.075,runs=wicket?0:x<.37?0:x<.68?1:x<.78?2:x<.94?4:6;innings.wickets+=wicket?1:0;innings.runs+=runs;innings.history.push(wicket?'W':runs);}return innings;}
 commit(id,events){if(this.completed||this.committed.has(id))return false;this.committed.add(id);const has=t=>events.some(e=>e.type===t),noBall=has('NoBallDetected'),wide=!noBall&&has('WideDetected'),boundary=events.find(e=>e.type==='BoundaryCrossed'),completedRuns=events.filter(e=>e.type==='RunCompleted').length,wicket=has('RunOut')||(!noBall&&(has('WicketBroken')||has('Caught'))),runs=!noBall&&(has('Caught')||has('WicketBroken'))?0:(boundary?.runs??completedRuns),extras=noBall||wide?1:0;const p=this.player;p.runs+=runs+extras;p.extras+=extras;if(!noBall&&!wide)p.balls++;if(wicket){p.wickets++;this.striker=this.nextBatter++;}else if(runs%2)[this.striker,this.nonStriker]=[this.nonStriker,this.striker];if(!noBall&&!wide&&p.balls%6===0)[this.striker,this.nonStriker]=[this.nonStriker,this.striker];p.history.push(wicket?'W':wide?'Wd':noBall?'Nb':runs);
 if((this.opponent&&p.runs>this.opponent.runs)||p.balls>=this.overs*6||p.wickets>=10){if(this.batFirst)this.opponent=this.simulateOpponent(p.runs+1);this.completed=true;const delta=p.runs-this.opponent.runs;this.result=delta===0?'MATCH TIED':delta>0?(this.batFirst?'YOU WIN BY '+delta+' RUNS':'YOU WIN BY '+(10-p.wickets)+' WICKETS'):(this.batFirst?'VISITORS WIN BY '+(10-this.opponent.wickets)+' WICKETS':'VISITORS WIN BY '+(-delta)+' RUNS');}return true;}
 get target(){return this.opponent?this.opponent.runs+1:null;}
 get oversText(){return Math.floor(this.player.balls/6)+'.'+this.player.balls%6;}
}
